nks/0b6f_zxj9ay~6.js\",\"/_next/static/chunks/143cg6c13uly6.js\",\"/_next/static/chunks/07vk.k35-e~ti.js\",\"/_next/static/chunks/0j6k6n9cniknh.js\",\"/_next/static/chunks/0.zxv9arc6a56.js\",\"/_next/static/chunks/00-zmo-3n1bt8.js\",\"/_next/static/chunks/0p4z5tusn0jt6.js\",\"/_next/static/chunks/01mcazkjru_is.js\"],\"default\"]\n6:[\"$\",\"$L22\",null,{\"pageId\":361,\"activeView\":{\"name\":\"default\",\"activeViewSuffix\":\"\",\"language\":\"en\"},\"children\":\"$@23\"}]\n9:null\ne:[[\"$\",\"title\",\"0\",{\"children\":\"Bhagavad-gītā As It Is 1.32-35\"}],[\"$\",\"meta\",\"1\",{\"name\":\"description\",\"content\":\"Srila Prabhupada''s books online\"}],[\"$\",\"meta\",\"2\",{\"name\":\"application-name\",\"content\":\"Vedabase\"}],[\"$\",\"link\",\"3\",{\"rel\":\"author\",\"href\":\"https://vedabase.io\"}],[\"$\",\"meta\",\"4\",{\"name\":\"author\",\"content\":\"A.C. Bhaktivedanta Swami - Srila Prabhupada\"}],[\"$\",\"meta\",\"5\",{\"name\":\"keywords\",\"content\":\"Srila Prabhupada,Krsna,Krishna,bhakti,devotion\"}],[\"$\",\"meta\",\"6\",{\"name\":\"creator\",\"content\":\"Prahlad Nrsimha das\"}]]\n"])self.__next_f.push([1,"25:T7a3,"])self.__next_f.push([1,"kim – what use; naḥ – to us; rājyena – is the kingdom; govinda – O Kṛṣṇa; kim – what; bhogaiḥ – enjoyment; jīvitena – living; vā – either; yeṣām – of whom; arthe – for the sake; kāṅkṣitam – is desired; naḥ – by us; rājyam – kingdom; bhogāḥ – material enjoyment; sukhāni – all happiness; ca – also; te – all of them; ime – these; avasthitāḥ – situated; yuddhe – on this battlefield; prāṇān – lives; tyaktvā – giving up; dhanāni – riches; ca – also; ācāryāḥ – teachers; pitaraḥ – fathers; putrāḥ – sons; tathā – as well as; eva – certainly; ca – also; pitāmahāḥ – grandfathers; mātulāḥ – maternal uncles; śvaśurāḥ – fathers-in-law; pautrāḥ – grandsons; śyālāḥ – brothers-in-law; sambandhinaḥ – relatives; tathā – as well as; etān – all these; na – never; hantum – to kill; icchāmi – do I wish; ghnataḥ – being killed; api – even; madhusūdana – O killer of the demon Madhu (Kṛṣṇa); api – even if; trai-lokya – of the three worlds; rājyasya – for the kingdom; hetoḥ – in exchange; kim nu – what to speak of; mahī-kṛte – for the sake of the earth; nihatya – by killing; dhārtarāṣṭrān – the sons of Dhṛtarāṣṭra; naḥ – our; kā – what; prītiḥ – pleasure; syāt – will there be; janārdana – O maintainer of all living entities."])self.__next_f.push([1,"26:T969,"])self.__next_f.push([1,"Arjuna has addressed Lord Kṛṣṇa as Govinda because Kṛṣṇa is the object of all pleasures for cows and the senses. By using this significant word, Arjuna indicates that Kṛṣṇa should understand what will satisfy Arjuna’s senses. But Govinda is not meant for satisfying our senses. If we try to satisfy the senses of Govinda, however, then automatically our own senses are satisfied. Materially, everyone wants to satisfy his senses, and he wants God to be the order supplier for such satisfaction. The Lord will satisfy the senses of the living entities as much as they deserve, but not to the extent that they may covet. But when one takes the opposite way – namely, when one tries to satisfy the senses of Govinda without desiring to satisfy one’s own senses – then by the grace of Govinda all desires of the living entity are satisfied. Arjuna’s deep affection for community and family members is exhibited here partly due to his natural compassion for them. He is therefore not prepared to fight. Everyone wants to show his opulence to friends and relatives, but Arjuna fears that all his relatives and friends will be killed on the battlefield and he will be unable to share his opulence after victory. This is a typical calculation of material life. The transcendental life, however, is different. Since a devotee wants to satisfy the desires of the Lord, he can, Lord willing, accept all kinds of opulence for the service of the Lord, and if the Lord is not willing, he should not accept a farthing. Arjuna did not want to kill his relatives, and if there were any need to kill them, he desired that Kṛṣṇa kill them personally. At this point he did not know that Kṛṣṇa had already killed them before their coming into the battlefield and that he was only to become an instrument for Kṛṣṇa. This fact is disclosed in following chapters. As a natural devotee of the Lord, Arjuna did not like to retaliate against his miscreant cousins and brothers, but it was the Lord’s plan that they should all be killed. The devotee of the Lord does not retaliate against the wrongdoer, but the Lord does not tolerate any mischief done to the devotee by the miscreants. The Lord can excuse a person on His own account, but He excuses no one who has done harm to His devotees. Therefore the Lord was determined to kill the miscreants, although Arjuna wanted to excuse them."])self.__next_f.push([1,"23:[\"$\",\"div\",null,{\"className\":\"flex flex-col min-h-screen text-vb-normal-text\",\"children\":[[\"$\",\"$L1a\",null,{\"className\":\"w-full left-0 z-30 bg-vb-body/95\",\"children\":[\"$\",\"$L1b\",null,{\"mainMenu\":\"$L24\",\"page\":{\"id\":361,\"meta\":{\"type\":\"books.Verse\",\"slug\":\"32-35\",\"show_in_menus\":false,\"seo_title\":\"\",\"search_description\":\"\",\"first_published_at\":null,\"alias_of\":null,\"locale\":\"en\"},\"title\":\"TEXTS 32-35\",\"advanced_view_url_path\":\"/en/library/bg/1/advanced-view/#bb331\",\"language_menu\":[{\"display_name\":\"አማርኛ (Ethiopian)\",\"language_code\":\"am\",\"enabled\":false,\"url_path\":\"/am/\"},{\"display_name\":\"Български (Bulgarian)\",\"language_code\":\"bg\",\"enabled\":true,\"url_path\":\"/bg/library/bg/1/32-35/\"},{\"display_name\":\"Čeština (Czech)\",\"language_code\":\"cs\",\"enabled\":true,\"url_path\":\"/cs/library/bg/1/32-35/\"},{\"display_name\":\"Dansk (Danish)\",\"language_code\":\"da\",\"enabled\":true,\"url_path\":\"/da/library/bg/1/32-35/\"},{\"display_name\":\"Deutsch (German)\",\"language_code\":\"de\",\"enabled\":true,\"url_path\":\"/de/library/bg/1/32-35/\"}