tion\":\"grandsons\"},{\"word\":\"śyālāḥ\",\"translation\":\"brothers-in-law\"},{\"word\":\"sambandhinaḥ\",\"translation\":\"relatives\"},{\"word\":\"tathā\",\"translation\":\"as well as\"},{\"word\":\"etān\",\"translation\":\"all these\"},{\"word\":\"na\",\"translation\":\"never\"},{\"word\":\"hantum\",\"translation\":\"to kill\"},{\"word\":\"icchāmi\",\"translation\":\"do I wish\"},{\"word\":\"ghnataḥ\",\"translation\":\"being killed\"},{\"word\":\"api\",\"translation\":\"even\"},{\"word\":\"madhusūdana\",\"translation\":\"O killer of the demon Madhu (Kṛṣṇa)\"},{\"word\":\"api\",\"translation\":\"even if\"},{\"word\":\"trai-lokya\",\"translation\":\"of the three worlds\"},{\"word\":\"rājyasya\",\"translation\":\"for the kingdom\"},{\"word\":\"hetoḥ\",\"translation\":\"in exchange\"},{\"word\":\"kim nu\",\"translation\":\"what to speak of\"},{\"word\":\"mahī-kṛte\",\"translation\":\"for the sake of the earth\"},{\"word\":\"nihatya\",\"translation\":\"by killing\"},{\"word\":\"dhārtarāṣṭrān\",\"translation\":\"the sons of Dhṛtarāṣṭra\"},{\"word\":\"naḥ\",\"translation\":\"our\"},{\"word\":\"kā\",\"translation\":\"what\"},{\"word\":\"prītiḥ\",\"translation\":\"pleasure\"},{\"word\":\"syāt\",\"translation\":\"will there be\"},{\"word\":\"janārdana\",\"translation\":\"O maintainer of all living entities\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":368,\"bb\":337,\"url_path\":\"/en/library/bg/1/32-35/b337/\",\"body_value\":\"O Govinda, of what avail to us are a kingdom, happiness or even life itself when all those for whom we may desire them are now arrayed on this battlefield? O Madhusūdana, when teachers, fathers, sons, grandfathers, maternal uncles, fathers-in-law, grandsons, brothers-in-law and other relatives are ready to give up their lives and properties and are standing before me, why should I wish to kill them, even though they might otherwise kill m